"use client";

import { UseFormRegister, FieldErrors, UseFormWatch, UseFormSetValue } from "react-hook-form";
import { ExpertFormData } from "./types";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Upload } from "lucide-react";
import { useRef } from "react";
import { useLanguage } from "@/contexts/LanguageContext";

interface ExpertBasicInfoFormProps {
  register: UseFormRegister<ExpertFormData>;
  errors: FieldErrors<ExpertFormData>;
  watch: UseFormWatch<ExpertFormData>;
  setValue: UseFormSetValue<ExpertFormData>;
  imagePreview: string | null;
  setImagePreview: (value: string | null) => void;
}

export function ExpertBasicInfoForm({
  register,
  errors,
  watch,
  setValue,
  imagePreview,
  setImagePreview,
}: ExpertBasicInfoFormProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { t } = useLanguage();

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setValue("image", file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };
  const imageValue = watch("image");
  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <div className="w-20 h-20 rounded-lg bg-gray-100 border-2 border-dashed border-gray-300 flex items-center justify-center overflow-hidden flex-shrink-0">
          {imagePreview ? (
            <img
              src={imagePreview}
              alt="Preview"
              className="w-full h-full object-cover"
            />
          ) : (
            <Upload className="h-8 w-8 text-gray-400" />
          )}
        </div>
        <div className="flex-1">
          <div className="relative">
            <input
              type="file"
              id="image-upload"
              ref={fileInputRef}
              className="sr-only"
              accept="image/svg+xml,image/png,image/jpeg,image/jpg,image/gif"
              onChange={handleImageUpload}
            />
            <label
              htmlFor="image-upload"
              className="inline-flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50 cursor-pointer"
            >
              {t("experts.edit.form.chooseFile") || "Choose files"}
            </label>
            <span className="ml-3 text-sm text-gray-500">
              {imageValue ? (imageValue as File).name : t("experts.edit.form.noFileChosen") || "No file chosen"}
            </span>
          </div>
          <p className="text-xs text-gray-500 mt-2">
            {t("experts.edit.form.uploadSupportEdit") || "SVG, PNG, JPG or GIF (MAX. 800x400px)."}
          </p>
        </div>
      </div>
      <div>
        <Label htmlFor="display_name" className="required">
          {t("experts.edit.form.displayName") || "Full Name"} <span className="text-red-500">*</span>
        </Label>
        <Input
          id="display_name"
          placeholder={t("experts.edit.form.displayNamePlaceholder") || "Dr. Sarah Johnson"}
          error={!!errors.display_name}
          {...register("display_name")}
          className="mt-1"
        />
        {errors.display_name && (
          <p className="text-xs text-red-500 mt-1">
            {errors.display_name.message}
          </p>
        )}
      </div>
      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="email" className="required">
            {t("experts.edit.form.email") || "Email Address"} <span className="text-red-500">*</span>
          </Label>
          <Input
            id="email"
            type="email"
            placeholder={t("experts.edit.form.emailPlaceholder") || "expert@email.com"}
            error={!!errors.email}
            {...register("email")}
            className="mt-1"
          />
          {errors.email && (
            <p className="text-xs text-red-500 mt-1">
              {errors.email.message}
            </p>
          )}
        </div>
        <div>
          <Label htmlFor="phone_number" className="required">
            {t("experts.edit.form.phoneNumber") || "Phone Number"} <span className="text-red-500">*</span>
          </Label>
          <Input
            id="phone_number"
            placeholder={t("experts.edit.form.phoneNumberPlaceholder") || "+211099530315"}
            error={!!errors.phone_number}
            {...register("phone_number")}
            className="mt-1"
          />
          {errors.phone_number && (
            <p className="text-xs text-red-500 mt-1">
              {errors.phone_number.message}
            </p>
          )}
        </div>
      </div>
      <div>
        <Label htmlFor="bio" className="required">
          {t("experts.edit.form.bio") || "Professional Bio"} <span className="text-red-500">*</span>
        </Label>
        <Textarea
          id="bio"
          placeholder={t("experts.edit.form.bioPlaceholder") || "Write about your professional background..."}
          error={!!errors.bio}
          {...register("bio")}
          className="mt-1"
          rows={4}
        />
        {errors.bio && (
          <p className="text-xs text-red-500 mt-1">
            {errors.bio.message}
          </p>
        )}
      </div>
    </div>
  );
}
