"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { getExpertSchema } from "@/validators/expertSchema";
import { useLanguage } from "@/contexts/LanguageContext";
import { useQuery } from "@tanstack/react-query";
import { useSession } from "next-auth/react";
import { Modal } from "@/components/ui/modal";
import { Button } from "@/components/ui/button";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { useExpertActions } from "@/hooks/use-expert-actions";
import { ExpertBasicInfoForm } from "./add-expert-modal-components/ExpertBasicInfoForm";
import { ExpertProfessionalForm } from "./add-expert-modal-components/ExpertProfessionalForm";
import { ExpertFormData, Certifications } from "./add-expert-modal-components/types";
import { API_BASE_URL, DASHBOARD_API_BASE_URL } from "@/data/config";

interface AddExpertModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function AddExpertModal({ isOpen, onClose }: AddExpertModalProps) {
  const { data: session } = useSession();
  const { createExpert, isCreating } = useExpertActions();
  const { t } = useLanguage();
  const [currentStep, setCurrentStep] = useState(1);
  const [certifications, setCertifications] = useState<Certifications[]>([
    { cert_name: "" },
  ]);
  const [selectedLanguages, setSelectedLanguages] = useState<number[]>([]);
  const [selectedCategories, setSelectedCategories] = useState<number[]>([]);
  const [selectedCountries, setSelectedCountries] = useState<number[]>([]);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const apiWithoutDashboard = API_BASE_URL;
  const apiDashboard = DASHBOARD_API_BASE_URL;

  const { data: languagesData } = useQuery({
    queryKey: ["expert-languages"],
    queryFn: async () => {
      const token = session?.user?.accessToken;
      if (!token) throw new Error("Not authenticated");
      const response = await fetch(
        `${apiWithoutDashboard}/experts/languages`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );
      if (!response.ok) {
        throw new Error("Failed to fetch languages");
      }
      return response.json();
    },
    enabled: !!session?.user?.accessToken && isOpen,
  });
  const { data: categoriesData } = useQuery({
    queryKey: ["expert-categories"],
    queryFn: async () => {
      const token = session?.user?.accessToken;
      if (!token) throw new Error("Not authenticated");
      const response = await fetch(
        `${apiWithoutDashboard}/experts/categories`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );
      if (!response.ok) {
        throw new Error("Failed to fetch categories");
      }
      return response.json();
    },
    enabled: !!session?.user?.accessToken && isOpen,
  });
  const { data: countriesData } = useQuery({
    queryKey: ["countries"],
    queryFn: async () => {
      const token = session?.user?.accessToken;
      if (!token) throw new Error("Not authenticated");
      const response = await fetch(
        `${apiDashboard}/countries`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );
      if (!response.ok) {
        throw new Error("Failed to fetch countries");
      }
      return response.json();
    },
    enabled: !!session?.user?.accessToken && isOpen,
  });
  const languages = languagesData?.data || [];
  const categories = categoriesData?.data || [];
  const countries = countriesData || [];
  const {
    register,
    handleSubmit,
    setValue,
    watch,
    reset,
    control,
    formState: { errors },
  } = useForm<ExpertFormData>({
    resolver: zodResolver(getExpertSchema(t)),
    defaultValues: {
      image: null,
      display_name: "",
      title: "",
      email: "",
      phone_number: "",
      bio: "",
      years_experience: 0,
      certifications: [],
      website: "",
      linkedin: "",
      languages: [],
      categories: [],
      countries: [],
      podcast: false,
    },
  });
  const handleClose = () => {
    reset();
    setCertifications([{ cert_name: "" }]);
    setSelectedLanguages([]);
    setSelectedCategories([]);
    setSelectedCountries([]);
    setImagePreview(null);
    setCurrentStep(1);
    onClose();
  };
  const onSubmit = async (data: ExpertFormData) => {
    try {
      const token = session?.user?.accessToken;
      if (!token) throw new Error("Not authenticated");
      const formData = new FormData();
      formData.append("email", data.email);
      formData.append("phone_number", data.phone_number);
      formData.append("display_name", data.display_name);
      if (data.title) formData.append("title", data.title);
      if (data.bio) formData.append("bio", data.bio);
      if (data.years_experience !== undefined && data.years_experience !== "") {
        formData.append("years_experience", data.years_experience.toString());
      }
      const filteredCerts = certifications.filter(
        (c) => c.cert_name?.trim() !== "" && c.cert_name !== undefined,
      );
      if (filteredCerts.length > 0) {
        filteredCerts.forEach((cert, index) => {
          formData.append(
            `certifications[${index}][cert_name]`,
            cert.cert_name!,
          );
        });
      }
      if (data.website) formData.append("website", data.website);
      if (data.linkedin) formData.append("linkedin", data.linkedin);
      if (data.languages.length > 0) {
        data.languages.forEach((lang, index) => {
          formData.append(`languages[${index}]`, lang.toString());
        });
      }
      if (data.categories.length > 0) {
        data.categories.forEach((cat, index) => {
          formData.append(`categories[${index}]`, cat.toString());
        });
      }
      if (data.countries.length > 0) {
        data.countries.forEach((country, index) => {
          formData.append(`countries[${index}]`, country.toString());
        });
      }
      formData.append("podcast", data.podcast ? "1" : "0");
      if (data.image) {
        formData.append("photo", data.image);
      }
      await createExpert(formData);
      handleClose();
    } catch (error) {
      console.error("Failed to create expert:", error);
    }
  };
  const nextStep = () => {
    setCurrentStep(2);
  };
  const prevStep = () => {
    setCurrentStep(1);
  };
  return (
    <Modal
      isOpen={isOpen}
      onClose={handleClose}
      title={t("experts.addNewExpert") || "Add New Expert"}
      size="xl"
      showCloseButton={false}
      footer={
        <div className="flex gap-3 justify-between w-full">
          <div>
            {currentStep === 2 && (
              <Button
                variant="outline"
                onClick={prevStep}
                disabled={isCreating}
                className="gap-2"
              >
                <ChevronLeft className="h-4 w-4" />
                {t("experts.edit.buttons.previous") || "Previous"}
              </Button>
            )}
          </div>
          <div className="flex gap-3">
            <Button
              variant="outline"
              onClick={handleClose}
              disabled={isCreating}
            >
              {t("experts.edit.buttons.cancel") || "Cancel"}
            </Button>
            {currentStep === 1 ? (
              <Button
                className="bg-teal-600 hover:bg-teal-700 text-white gap-2"
                onClick={nextStep}
              >
                {t("experts.edit.buttons.next") || "Next"}
                <ChevronRight className="h-4 w-4" />
              </Button>
            ) : (
              <Button
                className="bg-teal-600 hover:bg-teal-700 text-white"
                onClick={handleSubmit(onSubmit)}
                disabled={isCreating}
              >
                {isCreating ? t("experts.messages.adding") || "Adding..." : t("experts.addNewExpert") || "Add Expert"}
              </Button>
            )}
          </div>
        </div>
      }
    >
      <div className="max-h-[calc(100vh-280px)] overflow-y-auto pr-2">
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
          {currentStep === 1 && (
            <ExpertBasicInfoForm
              register={register}
              errors={errors}
              watch={watch}
              setValue={setValue}
              imagePreview={imagePreview}
              setImagePreview={setImagePreview}
            />
          )}
          {currentStep === 2 && (
            <ExpertProfessionalForm
              register={register}
              control={control}
              errors={errors}
              setValue={setValue}
              categories={categories}
              languages={languages}
              countries={countries}
              selectedCategories={selectedCategories}
              setSelectedCategories={setSelectedCategories}
              selectedLanguages={selectedLanguages}
              setSelectedLanguages={setSelectedLanguages}
              selectedCountries={selectedCountries}
              setSelectedCountries={setSelectedCountries}
              certifications={certifications}
              setCertifications={setCertifications}
            />
          )}
        </form>
      </div>
    </Modal>
  );
}
